(() => {
  'use strict';
  const M = window.AtinoManager;
  const E = window.AtinoERP;
  const Search = window.AtinoSearch;
  const tiers = ['Đồng', 'Bạc', 'Vàng', 'Kim cương'];
  const ui = {customerQuery:'', customerTier:'all', customerStatus:'active', staffQuery:'', staffStatus:'all', staffTab:'profiles', staffMonth:'', voucherQuery:'', voucherStatus:'all'};
  const esc = value => M.esc(value == null ? '' : value);
  const cash = value => M.money(Number(value) || 0);
  const arr = (data,key) => Array.isArray(data[key]) ? data[key] : [];
  const numeric = (form,key) => Number(form.elements[key]?.value || 0);
  const val = (form,key) => String(form.elements[key]?.value || '').trim();
  const selected = (a,b) => a === b ? ' selected' : '';
  const checked = value => value ? ' checked' : '';
  const dateOnly = value => {
    if (!value) return 'Chưa cập nhật';
    const match = String(value).match(/^(\d{4})-(\d{2})-(\d{2})/);
    return match ? `${match[3]}/${match[2]}/${match[1]}` : M.date(value);
  };
  const stat = (label,value,note='') => `<div class="am-stat"><div class="am-stat-top"><span>${esc(label)}</span></div><strong>${esc(value)}</strong>${note?`<p>${esc(note)}</p>`:''}</div>`;
  const tierBadge = tier => M.badge(tier || 'Đồng', tier === 'Vàng' ? 'amber' : tier === 'Kim cương' ? 'blue' : 'neutral');
  const isBirthday = person => Boolean(person.birthday && person.birthday.slice(5) === M.today().slice(5));
  const field = (label,name,value='',attrs='',type='text') => `<label class="am-field">${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
  const area = (label,name,value='',attrs='') => `<label class="am-field am-span-2">${esc(label)}<textarea name="${esc(name)}" rows="3" ${attrs}>${esc(value)}</textarea></label>`;
  const selectField = (label,name,options,value,attrs='') => `<label class="am-field">${esc(label)}<select name="${esc(name)}" ${attrs}>${options.map(([v,t])=>`<option value="${esc(v)}"${selected(value,v)}>${esc(t)}</option>`).join('')}</select></label>`;
  const activeField = (active=true,disabled=false) => `<label class="amp-check am-span-2"><input name="active" type="checkbox"${checked(active)}${disabled?' disabled':''}><span>Đang hoạt động</span></label>`;
  const panelHead = (title,desc='',actions='') => `<div class="am-panel-head"><div><h2>${esc(title)}</h2>${desc?`<p class="am-muted">${esc(desc)}</p>`:''}</div>${actions?`<div class="am-actions">${actions}</div>`:''}</div>`;
  const formError = (form,message) => { let el=form.querySelector('[data-local-error]'); if(!el){el=document.createElement('p');el.className='am-error';el.dataset.localError='';el.setAttribute('role','alert');form.append(el);} const text=String(message||'');el.textContent=text;el.hidden=!text.trim(); };
  const numberFormat = n => new Intl.NumberFormat('vi-VN',{maximumFractionDigits:1}).format(n || 0);
  const refreshSaved = async message => { await M.refresh(); M.toast(message); };
  const style = document.createElement('style');
  style.textContent = `
    #manager-app .amp-person{display:flex;gap:.75rem;align-items:center}#manager-app .amp-avatar{flex:none;width:2.6rem;height:2.6rem;border-radius:.8rem;background:#eef2ff;color:#3730a3;display:grid;place-items:center;font-weight:750;font-size:.9rem}#manager-app .amp-person strong{display:block}#manager-app .amp-person small{display:block;color:#64748b;margin-top:.2rem;font-size:.82rem}#manager-app .amp-row-sub{display:block;color:#64748b;font-size:.86rem;margin-top:.25rem}#manager-app .amp-birthday{color:#a16207;font-size:.85rem;display:block;margin-top:.3rem}#manager-app .amp-tabs{display:flex;gap:.35rem;flex-wrap:wrap;padding:.35rem;background:#e9eef5;border-radius:.8rem;width:fit-content;margin-bottom:1.25rem}#manager-app .amp-tabs button{border:0;background:transparent;color:#526176;font:inherit;font-size:.9rem;font-weight:600;padding:.65rem 1rem;border-radius:.6rem;cursor:pointer}#manager-app .amp-tabs button[aria-selected=true]{background:#fff;color:#312e81;box-shadow:0 1px 5px #1e293b12}#manager-app .amp-keyline{padding:1rem 0;border-bottom:1px solid #edf0f5}#manager-app .amp-keyline:last-child{border-bottom:0}#manager-app .amp-policy-tag{display:inline-flex;align-items:center;border-radius:.5rem;background:#eef2ff;color:#4338ca;padding:.35rem .6rem;font-size:.84rem;font-weight:600;margin-bottom:.8rem}#manager-app .amp-policy-numbers{display:flex;align-items:baseline;gap:.5rem;margin:.5rem 0 1rem}#manager-app .amp-policy-numbers strong{font-size:2.3rem;letter-spacing:-.05em;color:#172554}#manager-app .amp-policy-numbers span{color:#64748b}#manager-app .amp-tier-track{height:.45rem;border-radius:1rem;background:#e2e8f0;overflow:hidden;margin:.65rem 0}#manager-app .amp-tier-track span{display:block;height:100%;background:#6366f1;border-radius:1rem}#manager-app .amp-note-lines p{margin:.4rem 0}#manager-app .amp-voucher-code{font-family:ui-monospace,SFMono-Regular,monospace;font-weight:750;color:#3730a3;background:#eef2ff;padding:.3rem .5rem;border:1px dashed #a5b4fc;border-radius:.35rem;display:inline-block;letter-spacing:.03em}#manager-app .amp-section-note{display:flex;gap:.75rem;align-items:flex-start;padding:1rem 1.2rem;border-radius:.8rem;background:#f0f4ff;border:1px solid #dce5ff;color:#334155;font-size:.94rem;line-height:1.6;margin:0 0 1.2rem}#manager-app .amp-settings-form{display:grid;gap:1rem}#manager-app .amp-settings-form .am-form-grid{margin:0}#manager-app .amp-check{display:flex!important;align-items:center;gap:.6rem;font-size:.95rem;line-height:1.5}#manager-app .amp-check input[type=checkbox]{width:1.1rem!important;height:1.1rem!important;margin:0!important;accent-color:#4f46e5}#manager-app .amp-full{grid-column:1/-1}#manager-app .amp-contact{white-space:normal;min-width:9rem}#manager-app .amp-min{min-width:8rem}#manager-app .amp-policy-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.3rem}#manager-app .amp-policy-grid>.am-panel{margin:0}#manager-app .amp-salary-note{font-size:.875rem;color:#64748b;line-height:1.6;margin-top:1rem}#manager-app .amp-count{white-space:nowrap;color:#64748b;font-size:.875rem}@media(max-width:850px){#manager-app .amp-policy-grid{grid-template-columns:1fr}#manager-app .amp-full{grid-column:auto}}`;
  document.head.append(style);

  // Customers -------------------------------------------------------------
  const customerSearchText = c => [c.id, c.name, c.phone, c.email];
  function customersFiltered() {
    return arr(M.data,'customers').filter(c => Search.match(customerSearchText(c), ui.customerQuery) && (ui.customerTier==='all'||(c.tier||'Đồng')===ui.customerTier) && (ui.customerStatus==='all'||(ui.customerStatus==='active' ? c.active!==false : c.active===false)));
  }
  function customerRows() {
    const rows=customersFiltered();
    if(!rows.length) return `<tr><td colspan="7">${M.empty('Chưa có khách hàng phù hợp')}</td></tr>`;
    return rows.map(c=>`<tr><td><div class="amp-person"><span class="amp-avatar">${esc((c.name||'KH').split(/\s+/).slice(-2).map(x=>x[0]).join('').toUpperCase())}</span><div><strong>${esc(c.name)}</strong><small>${esc(c.id)}${c.active===false?' · Ngừng theo dõi':''}</small></div></div></td><td class="amp-contact">${esc(c.phone||'—')}${c.email?`<small class="amp-row-sub">${esc(c.email)}</small>`:''}</td><td>${esc(c.birthday?dateOnly(c.birthday):'Chưa cập nhật')}${isBirthday(c)?'<span class="amp-birthday">Sinh nhật hôm nay</span>':''}</td><td>${tierBadge(c.tier)}</td><td><strong>${cash(c.spend)}</strong><small class="amp-row-sub">${Number(c.orderCount)||0} đơn đã mua</small></td><td>${c.lastPurchase?esc(dateOnly(c.lastPurchase)):'—'}</td><td><div class="am-actions"><button type="button" class="am-btn secondary small" data-customer-detail="${esc(c.id)}">Chi tiết</button><button type="button" class="am-btn ghost small" data-customer-edit="${esc(c.id)}" aria-label="Sửa ${esc(c.name)}">Sửa</button></div></td></tr>`).join('');
  }
  function customerForm(customer=null) {
    const c=customer||{};
    M.dialog({title:c.id?'Sửa hồ sơ khách hàng':'Thêm khách hàng',wide:true,submitLabel:c.id?'Lưu hồ sơ':'Thêm khách hàng',body:`<div class="am-form-grid">${field('Họ và tên *','name',c.name,'required maxlength="100" autocomplete="name"')}${field('Số điện thoại *','phone',c.phone,'required minlength="8" maxlength="25" autocomplete="tel"','tel')}${field('Ngày sinh','birthday',c.birthday,`max="${M.today()}"`,'date')}${field('Email','email',c.email,'maxlength="150" autocomplete="email"','email')}${field('Địa chỉ','address',c.address,'maxlength="300" autocomplete="street-address"')}${selectField('Trạng thái','status',[['active','Đang theo dõi'],['inactive','Ngừng theo dõi']],c.active===false?'inactive':'active')}${area('Ghi chú','note',c.note,'maxlength="1000"')}</div>`,onSubmit:async form=>{
      await E.saveCustomer({id:c.id,name:val(form,'name'),phone:val(form,'phone'),birthday:val(form,'birthday'),email:val(form,'email'),address:val(form,'address'),note:val(form,'note'),active:val(form,'status')==='active'});
      await refreshSaved(c.id?'Đã cập nhật hồ sơ khách hàng.':'Đã thêm khách hàng.');
    }});
  }
  function customerDetail(c) {
    const purchases=arr(M.data,'movements').filter(d=>d.customerId===c.id&&(d.type==='sale'||d.type==='exchange')).sort((a,b)=>(b.when||0)-(a.when||0));
    const purchaseIds=new Set(purchases.map(d=>d.id));
    const returns=arr(M.data,'returns').filter(r=>purchaseIds.has(r.invoiceId));
    const settings=M.data.settings||{};
    const thresholds=[['Bạc',Number(settings.tierSilver)||2000000],['Vàng',Number(settings.tierGold)||5000000],['Kim cương',Number(settings.tierDiamond)||10000000]];
    const next=thresholds.find(([,threshold])=>(Number(c.spend)||0)<threshold);
    const progress=next?Math.min(100,((Number(c.spend)||0)/next[1])*100):100;
    const detailLine=(name,value)=>`<div><dt class="am-muted">${esc(name)}</dt><dd>${esc(value||'Chưa cập nhật')}</dd></div>`;
    M.dialog({title:c.name,wide:true,submitLabel:'Đóng',body:`<div class="am-toolbar"><span class="amp-count">${esc(c.id)}</span>${tierBadge(c.tier)}${c.active===false?M.badge('Ngừng theo dõi','neutral'):''}${isBirthday(c)?M.badge('Sinh nhật hôm nay','amber'):''}</div><div class="am-stat-grid">${stat('Tổng chi tiêu',cash(c.spend))}${stat('Đơn hàng',String(c.orderCount||0))}${stat('Lần đổi hàng',String(returns.length))}</div><dl class="am-form-grid amp-keyline">${detailLine('Số điện thoại',c.phone)}${detailLine('Ngày sinh',c.birthday?dateOnly(c.birthday):'')}${detailLine('Email',c.email)}${detailLine('Địa chỉ',c.address)}</dl><div class="amp-keyline"><strong>${next?`Còn ${cash(next[1]-(Number(c.spend)||0))} để lên hạng ${esc(next[0])}`:'Đang ở hạng thành viên cao nhất'}</strong><div class="amp-tier-track"><span style="width:${progress.toFixed(2)}%"></span></div></div>${c.note?`<div class="am-note">${esc(c.note)}</div>`:''}<h3>Lịch sử giao dịch</h3><div class="am-table-wrap"><table class="am-table"><thead><tr><th>Chứng từ</th><th>Ngày</th><th>Nội dung</th><th>Thực thu</th></tr></thead><tbody>${purchases.length?purchases.map(d=>`<tr><td>${esc(d.id)}</td><td>${esc(M.date(d.when))}</td><td>${d.type==='exchange'?'Thu chênh lệch đổi hàng':'Mua hàng'}${d.promotion&&d.promotion!=='none'?`<small class="amp-row-sub">${d.promotion==='birthday'?'Ưu đãi sinh nhật':esc(d.promotionName||arr(M.data,'vouchers').find(v=>v.code===d.voucherCode)?.name||'Ưu đãi tự động')}</small>`:''}</td><td>${cash(d.total??d.extraPaid??(d.items||[]).reduce((n,l)=>n+l.qty*l.unitPrice,0))}</td></tr>`).join(''):`<tr><td colspan="4">${M.empty('Chưa có giao dịch')}</td></tr>`}</tbody></table></div>`});
  }
  M.register('customers',{title:'Khách hàng',kicker:'Chăm sóc & thành viên',render(){
    const customers=arr(M.data,'customers');
    const month=M.today().slice(5,7);
    const birthdays=customers.filter(c=>c.active!==false&&c.birthday?.slice(5,7)===month);
    return `<div class="am-stat-grid">${stat('Khách hàng',String(customers.filter(c=>c.active!==false).length))}${stat('Hạng Vàng & Kim cương',String(customers.filter(c=>['Vàng','Kim cương'].includes(c.tier)).length))}${stat('Sinh nhật tháng này',String(birthdays.length),`Hôm nay: ${customers.filter(c=>c.active!==false&&isBirthday(c)).length}`)}${stat('Chi tiêu đã ghi nhận',cash(customers.reduce((n,c)=>n+(Number(c.spend)||0),0)))}</div><div class="am-panel">${panelHead('Danh sách khách hàng','',`<button type="button" class="am-btn secondary" data-customers-export>Xuất CSV</button><button type="button" class="am-btn" data-customer-add>Thêm khách hàng</button>`)}<div class="am-toolbar"><input class="am-search" type="search" data-customer-query placeholder="Tìm tên, mã, số điện thoại…" aria-label="Tìm khách hàng" value="${esc(ui.customerQuery)}"><select data-customer-tier aria-label="Lọc hạng thành viên"><option value="all">Tất cả hạng</option>${tiers.map(t=>`<option${selected(ui.customerTier,t)}>${esc(t)}</option>`).join('')}</select><select data-customer-status aria-label="Trạng thái khách hàng"><option value="active"${selected(ui.customerStatus,'active')}>Đang theo dõi</option><option value="inactive"${selected(ui.customerStatus,'inactive')}>Ngừng theo dõi</option><option value="all"${selected(ui.customerStatus,'all')}>Tất cả trạng thái</option></select><span class="amp-count" data-customer-count>${customersFiltered().length} khách hàng</span></div><div class="am-table-wrap"><table class="am-table"><thead><tr><th>Khách hàng</th><th>Liên hệ</th><th>Ngày sinh</th><th>Hạng</th><th>Chi tiêu</th><th>Mua gần nhất</th><th>Thao tác</th></tr></thead><tbody data-customer-rows>${customerRows()}</tbody></table></div></div>`;
  },bind(root){
    const update=()=>{root.querySelector('[data-customer-rows]').innerHTML=customerRows();root.querySelector('[data-customer-count]').textContent=customersFiltered().length+' khách hàng';};
    root.querySelector('[data-customer-query]').addEventListener('input',e=>{ui.customerQuery=e.target.value;update();});
    root.querySelector('[data-customer-tier]').addEventListener('change',e=>{ui.customerTier=e.target.value;update();});
    root.querySelector('[data-customer-status]').addEventListener('change',e=>{ui.customerStatus=e.target.value;update();});
    Search.attach(root.querySelector('[data-customer-query]'), {items: () => customersFiltered().map(c => ({value: c.name, label: c.name, detail: [c.id, c.phone, c.tier || 'Đồng'].filter(Boolean).join(' · '), searchText: customerSearchText(c)}))});
    root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-customer-add'))customerForm();if(b.dataset.customerEdit){const c=arr(M.data,'customers').find(x=>x.id===b.dataset.customerEdit);if(c)customerForm(c);}if(b.dataset.customerDetail){const c=arr(M.data,'customers').find(x=>x.id===b.dataset.customerDetail);if(c)customerDetail(c);}if(b.hasAttribute('data-customers-export'))M.downloadCSV('Atino_khach_hang.csv',[['Mã khách hàng','Họ tên','Điện thoại','Ngày sinh','Hạng','Chi tiêu','Số đơn','Email','Địa chỉ','Trạng thái'],...customersFiltered().map(c=>[c.id,c.name,c.phone,c.birthday,c.tier,c.spend,c.orderCount,c.email,c.address,c.active===false?'Ngừng theo dõi':'Đang theo dõi'])]);});
  }});

  // Employees, schedule and salary estimates -------------------------------
  const shiftHours = s => {const a=String(s.start||'').split(':').map(Number),b=String(s.end||'').split(':').map(Number);return Math.max(0,((b[0]*60+b[1])-(a[0]*60+a[1]))/60)||0;};
  const monthShifts = () => arr(M.data,'shifts').filter(s=>String(s.date||'').startsWith(ui.staffMonth||M.today().slice(0,7)));
  const staffSearchText = s => [s.code, s.name, s.username, s.phone, s.jobTitle];
  const staffFiltered = () => arr(M.data,'staff').filter(s=>Search.match(staffSearchText(s),ui.staffQuery)&&(ui.staffStatus==='all'||(ui.staffStatus==='active'?s.active!==false:s.active===false)));
  function payrollRows(people=staffFiltered()){return people.map(s=>{const shifts=monthShifts().filter(x=>x.employeeId===s.code);const completed=shifts.filter(x=>x.status==='completed').reduce((n,x)=>n+shiftHours(x),0);const planned=shifts.reduce((n,x)=>n+shiftHours(x),0);const hourly=s.payType==='hourly';let pay=hourly?completed*(Number(s.hourlyRate)||0):(Number(s.baseSalary)||0);if(s.startDate&&s.startDate.slice(0,7)>(ui.staffMonth||M.today().slice(0,7)))pay=0;return{person:s,completed,planned,pay,hourly};});}
  function employeeForm(person=null){
    const p=person||{};const isSelf=p.code===M.data.user?.code;
    const profileOptions=(key,presets,emptyLabel)=>[['',emptyLabel],...[...new Set([...presets,...arr(M.data,'staff').map(row=>row[key]),p[key]])].filter(value=>typeof value==='string'&&value.trim()).map(value=>[value,value])];
    const jobOptions=profileOptions('jobTitle',['Quản lý cửa hàng','Ca trưởng','Nhân viên cửa hàng','Nhân viên bán hàng','Thu ngân'],'Chưa chọn chức vụ');
    const shiftOptions=profileOptions('defaultShift',['Ca sáng · 08:00–14:00','Ca chiều · 14:00–20:00'],'Theo lịch phân ca');
    M.dialog({title:p.code?'Sửa nhân viên · '+p.code:'Thêm nhân viên',wide:true,submitLabel:p.code?'Lưu thông tin':'Tạo nhân viên',body:`<div class="am-form-grid">${field('Họ và tên *','name',p.name,'required maxlength="100"')}${field('Số điện thoại','phone',p.phone,'maxlength="25"','tel')}${selectField('Chức vụ / công việc','jobTitle',jobOptions,p.jobTitle||'')}${field('Ngày vào làm','startDate',p.startDate,'','date')}${selectField('Cách tính lương','payType',[['monthly','Lương theo tháng'],['hourly','Lương theo giờ']],p.payType||'monthly')}${selectField('Ca làm thường lệ','defaultShift',shiftOptions,p.defaultShift||'')}${field('Lương tháng (đ)','baseSalary',p.baseSalary||0,'min="0" max="1000000000" step="1"','number')}${field('Lương giờ (đ/giờ)','hourlyRate',p.hourlyRate||0,'min="0" max="10000000" step="1"','number')}</div><h3 class="amp-keyline">Tài khoản đăng nhập</h3><div class="am-form-grid">${field('Tên đăng nhập *','username',p.username,`${p.code?'readonly':'minlength="3"'} required maxlength="50" autocomplete="off"`)}${selectField('Quyền tài khoản','role',[['employee','Nhân viên'],['manager','Quản lý']],p.role||'employee',isSelf?'disabled':'')}${field(p.code?'Mật khẩu mới (bỏ trống để giữ)':'Mật khẩu (từ 8 ký tự) *','password','',`${p.code?'':'required'} minlength="8" maxlength="256" autocomplete="new-password"`,'password')}${activeField(p.active!==false,isSelf)}</div>`,onOpen(form){const update=()=>{const hourly=form.elements.payType.value==='hourly';form.elements.baseSalary.closest('label').hidden=hourly;form.elements.hourlyRate.closest('label').hidden=!hourly;};form.elements.payType.addEventListener('change',update);update();},onSubmit:async form=>{
      await E.saveEmployee({code:p.code,name:val(form,'name'),phone:val(form,'phone'),jobTitle:val(form,'jobTitle'),startDate:val(form,'startDate'),payType:val(form,'payType'),defaultShift:val(form,'defaultShift'),baseSalary:numeric(form,'baseSalary'),hourlyRate:numeric(form,'hourlyRate'),username:val(form,'username'),password:form.elements.password.value,role:form.elements.role.value,active:form.elements.active.checked});
      await refreshSaved(p.code?'Đã cập nhật nhân viên.':'Đã tạo hồ sơ và tài khoản nhân viên.');
    }});
  }
  function shiftForm(shift=null){
    const s=shift||{};const people=arr(M.data,'staff').filter(p=>p.active!==false||p.code===s.employeeId);
    if(!people.length){M.toast('Cần có nhân viên hoạt động trước khi phân ca.');return;}
    M.dialog({title:s.id?'Sửa ca làm':'Phân ca làm việc',wide:true,body:`<div class="am-form-grid">${selectField('Nhân viên *','employeeId',people.map(p=>[p.code,p.code+' · '+p.name]),s.employeeId||people[0].code,'required')}${field('Ngày làm *','date',s.date||M.today(),'required','date')}${field('Bắt đầu *','start',s.start||'08:00','required','time')}${field('Kết thúc *','end',s.end||'14:00','required','time')}${selectField('Trạng thái','status',[['planned','Đã phân công'],['completed','Đã hoàn thành']],s.status||'planned')}${area('Ghi chú ca làm','note',s.note,'maxlength="500"')}</div>`,onSubmit:async form=>{
      const data={id:s.id,employeeId:val(form,'employeeId'),date:val(form,'date'),start:val(form,'start'),end:val(form,'end'),status:val(form,'status'),note:val(form,'note')};
      if(data.end<=data.start)throw new Error('Giờ kết thúc phải sau giờ bắt đầu trong cùng ngày.');
      if(data.status==='completed'&&data.date>M.today())throw new Error('Chưa thể xác nhận hoàn thành ca làm ở ngày tương lai.');
      await E.saveShift(data);await refreshSaved(s.id?'Đã cập nhật ca làm.':'Đã phân ca cho nhân viên.');
    }});
  }
  function removeShift(s){const p=arr(M.data,'staff').find(x=>x.code===s.employeeId);M.dialog({title:'Xóa ca làm',submitLabel:'Xóa ca',body:`<p>Xóa ca <strong>${esc(s.start)} – ${esc(s.end)}</strong> ngày <strong>${esc(dateOnly(s.date))}</strong> của <strong>${esc(p?.name||s.employeeId)}</strong>?</p>${s.status==='completed'?'<p class="am-note">Xóa ca đã hoàn thành sẽ cập nhật giờ công và dự toán lương.</p>':''}`,onSubmit:async()=>{await E.deleteShift(s.id);await refreshSaved('Đã xóa ca làm.');}});}
  function completeShift(s){if(s.date>M.today()){M.toast('Chưa thể hoàn thành ca ở ngày tương lai.');return;}M.dialog({title:'Xác nhận ca đã hoàn thành',submitLabel:'Xác nhận hoàn thành',body:`<p>Ca ngày <strong>${esc(dateOnly(s.date))}</strong>, từ <strong>${esc(s.start)} đến ${esc(s.end)}</strong>, thời lượng <strong>${numberFormat(shiftHours(s))} giờ</strong>.</p><p class="am-note">Xác nhận thời gian làm thực tế.</p>`,onSubmit:async()=>{await E.saveShift({...s,status:'completed'});await refreshSaved('Đã xác nhận hoàn thành ca làm.');}});}
  function employeeTable(){const people=staffFiltered();return `<div class="am-table-wrap"><table class="am-table"><thead><tr><th>Nhân viên</th><th>Chức vụ</th><th>Lương cấu hình</th><th>Thời gian làm</th><th>Tài khoản</th><th>Thao tác</th></tr></thead><tbody>${people.length?people.map(p=>`<tr><td><div class="amp-person"><span class="amp-avatar">${esc((p.name||'NV').split(/\s+/).slice(-2).map(x=>x[0]).join('').toUpperCase())}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.code)}${p.phone?' · '+esc(p.phone):''}</small></div></div></td><td>${esc(p.jobTitle||'Chưa cập nhật')}<small class="amp-row-sub">${p.role==='manager'?'Quyền Quản lý':'Quyền Nhân viên'}</small></td><td>${p.payType==='hourly'?(p.hourlyRate?cash(p.hourlyRate)+' / giờ':'Chưa cấu hình'):(p.baseSalary?cash(p.baseSalary)+' / tháng':'Chưa cấu hình')}</td><td>${esc(p.defaultShift||'Chưa có ca thường lệ')}<small class="amp-row-sub">Vào làm: ${esc(p.startDate?dateOnly(p.startDate):'Chưa cập nhật')}</small></td><td>${M.badge(p.active===false?'Đã khóa':'Đang hoạt động',p.active===false?'neutral':'green')}<small class="amp-row-sub">${esc(p.username)}</small></td><td><button type="button" class="am-btn secondary small" data-employee-edit="${esc(p.code)}">Xem / sửa</button></td></tr>`).join(''):`<tr><td colspan="6">${M.empty('Không tìm thấy nhân viên')}</td></tr>`}</tbody></table></div>`;}
  function shiftsTable(){const ids=new Set(staffFiltered().map(p=>p.code));const shifts=monthShifts().filter(s=>ids.has(s.employeeId)).sort((a,b)=>String(a.date).localeCompare(String(b.date))||String(a.start).localeCompare(String(b.start)));return `<div class="am-table-wrap"><table class="am-table"><thead><tr><th>Ngày làm</th><th>Nhân viên</th><th>Ca làm</th><th>Thời lượng</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>${shifts.length?shifts.map(s=>{const p=arr(M.data,'staff').find(x=>x.code===s.employeeId);return `<tr><td><strong>${esc(dateOnly(s.date))}</strong>${s.date===M.today()?'<small class="amp-row-sub">Hôm nay</small>':''}</td><td>${esc(p?.name||s.employeeId)}<small class="amp-row-sub">${esc(s.employeeId)}</small></td><td>${esc(s.start)} – ${esc(s.end)}${s.note?`<small class="amp-row-sub">${esc(s.note)}</small>`:''}</td><td>${numberFormat(shiftHours(s))} giờ</td><td>${M.badge(s.status==='completed'?'Đã hoàn thành':'Đã phân công',s.status==='completed'?'green':'blue')}</td><td><div class="am-actions"><button type="button" class="am-btn secondary small" data-shift-edit="${esc(s.id)}">Sửa</button>${s.status!=='completed'&&s.date<=M.today()?`<button type="button" class="am-btn ghost small" data-shift-complete="${esc(s.id)}">Hoàn thành</button>`:''}<button type="button" class="am-btn ghost small" data-shift-delete="${esc(s.id)}" aria-label="Xóa ca ngày ${esc(dateOnly(s.date))} của ${esc(p?.name||s.employeeId)}">Xóa</button></div></td></tr>`;}).join(''):`<tr><td colspan="6">${M.empty('Chưa có ca làm trong tháng')}</td></tr>`}</tbody></table></div>`;}
  function salaryTable(){const rows=payrollRows();return `<div class="am-table-wrap"><table class="am-table"><thead><tr><th>Nhân viên</th><th>Hình thức</th><th>Giờ phân công</th><th>Giờ hoàn thành</th><th>Mức lương</th><th>Dự toán tháng</th></tr></thead><tbody>${rows.length?rows.map(({person:p,completed,planned,pay,hourly})=>`<tr><td><strong>${esc(p.name)}</strong><small class="amp-row-sub">${esc(p.code)}</small></td><td>${hourly?'Theo giờ':'Theo tháng'}</td><td>${numberFormat(planned)} giờ</td><td>${numberFormat(completed)} giờ</td><td>${cash(hourly?p.hourlyRate:p.baseSalary)}${hourly?' / giờ':' / tháng'}</td><td><strong>${cash(pay)}</strong>${!(hourly?p.hourlyRate:p.baseSalary)?'<small class="amp-row-sub">Chưa cấu hình lương</small>':''}</td></tr>`).join(''):`<tr><td colspan="6">${M.empty('Chưa có nhân viên phù hợp')}</td></tr>`}</tbody><tfoot><tr><td colspan="5"><strong>Tổng dự toán theo bộ lọc</strong></td><td><strong>${cash(rows.reduce((n,x)=>n+x.pay,0))}</strong></td></tr></tfoot></table></div>`;}
  function staffContent(){return ui.staffTab==='shifts'?shiftsTable():ui.staffTab==='payroll'?salaryTable():employeeTable();}
  M.register('employees',{title:'Nhân viên & ca làm',kicker:'Nhân sự cửa hàng',render(){
    ui.staffMonth ||= M.today().slice(0,7);const staff=arr(M.data,'staff'),shifts=monthShifts(),completed=shifts.filter(s=>s.status==='completed');
    return `<div class="am-stat-grid">${stat('Nhân viên hoạt động',String(staff.filter(p=>p.active!==false).length))}${stat('Ca đã phân công',String(shifts.length),'Tháng '+ui.staffMonth.slice(5)+'/'+ui.staffMonth.slice(0,4))}${stat('Giờ đã hoàn thành',numberFormat(completed.reduce((n,s)=>n+shiftHours(s),0))+' giờ',`${completed.length} ca`)}${stat('Dự toán lương',cash(payrollRows(staff).reduce((n,x)=>n+x.pay,0)),'Tháng '+ui.staffMonth.slice(5)+'/'+ui.staffMonth.slice(0,4))}</div><div class="am-panel">${panelHead('Đội ngũ Atino','',`<button type="button" class="am-btn secondary" data-staff-export>Xuất CSV</button><button type="button" class="am-btn secondary" data-shift-add>Phân ca</button><button type="button" class="am-btn" data-employee-add>Thêm nhân viên</button>`)}<div class="amp-tabs" role="tablist" aria-label="Phân hệ nhân viên">${[['profiles','Hồ sơ nhân viên'],['shifts','Phân ca'],['payroll','Dự toán lương']].map(([v,t])=>`<button type="button" role="tab" aria-selected="${ui.staffTab===v}" data-staff-tab="${v}">${t}</button>`).join('')}</div><div class="am-toolbar"><input class="am-search" type="search" value="${esc(ui.staffQuery)}" data-staff-query placeholder="Tìm nhân viên, mã, chức vụ…" aria-label="Tìm nhân viên"><select data-staff-status aria-label="Lọc trạng thái nhân viên"><option value="all"${selected(ui.staffStatus,'all')}>Tất cả trạng thái</option><option value="active"${selected(ui.staffStatus,'active')}>Đang hoạt động</option><option value="inactive"${selected(ui.staffStatus,'inactive')}>Đã khóa</option></select><label class="amp-check">Tháng <input type="month" data-staff-month value="${esc(ui.staffMonth)}" aria-label="Tháng phân ca và lương"></label></div><div data-staff-content>${staffContent()}</div></div>`;
  },bind(root){
    const update=()=>{root.querySelector('[data-staff-content]').innerHTML=staffContent();};
    root.querySelector('[data-staff-query]').addEventListener('input',e=>{ui.staffQuery=e.target.value;update();});
    root.querySelector('[data-staff-status]').addEventListener('change',e=>{ui.staffStatus=e.target.value;M.go('employees');});
    root.querySelector('[data-staff-month]').addEventListener('change',e=>{if(e.target.value){ui.staffMonth=e.target.value;M.go('employees');}});
    Search.attach(root.querySelector('[data-staff-query]'), {items: () => staffFiltered().map(s => ({value: s.name, label: s.name, detail: [s.code, s.jobTitle, s.phone].filter(Boolean).join(' · '), searchText: staffSearchText(s)}))});
    root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.staffTab){ui.staffTab=b.dataset.staffTab;M.go('employees');}if(b.hasAttribute('data-employee-add'))employeeForm();if(b.dataset.employeeEdit){const p=arr(M.data,'staff').find(x=>x.code===b.dataset.employeeEdit);if(p)employeeForm(p);}if(b.hasAttribute('data-shift-add'))shiftForm();for(const [key,fn] of [['shiftEdit',shiftForm],['shiftDelete',removeShift],['shiftComplete',completeShift]])if(b.dataset[key]){const s=arr(M.data,'shifts').find(x=>x.id===b.dataset[key]);if(s)fn(s);}if(b.hasAttribute('data-staff-export')){if(ui.staffTab==='payroll')M.downloadCSV('Atino_du_toan_luong_'+ui.staffMonth+'.csv',[['Mã nhân viên','Họ tên','Hình thức','Giờ phân công','Giờ hoàn thành','Mức lương','Dự toán'],...payrollRows().map(x=>[x.person.code,x.person.name,x.hourly?'Theo giờ':'Theo tháng',x.planned,x.completed,x.hourly?x.person.hourlyRate:x.person.baseSalary,x.pay])]);else if(ui.staffTab==='shifts'){const ids=new Set(staffFiltered().map(p=>p.code));M.downloadCSV('Atino_phan_ca_'+ui.staffMonth+'.csv',[['Ngày','Mã nhân viên','Họ tên','Bắt đầu','Kết thúc','Số giờ','Trạng thái','Ghi chú'],...monthShifts().filter(s=>ids.has(s.employeeId)).map(s=>[s.date,s.employeeId,arr(M.data,'staff').find(p=>p.code===s.employeeId)?.name||'',s.start,s.end,shiftHours(s),s.status==='completed'?'Đã hoàn thành':'Đã phân công',s.note])]);}else M.downloadCSV('Atino_nhan_vien.csv',[['Mã','Họ tên','Điện thoại','Chức vụ','Ngày vào làm','Ca thường lệ','Hình thức lương','Lương tháng','Lương giờ','Quyền','Trạng thái'],...staffFiltered().map(p=>[p.code,p.name,p.phone,p.jobTitle,p.startDate,p.defaultShift,p.payType,p.baseSalary,p.hourlyRate,p.role==='manager'?'Quản lý':'Nhân viên',p.active===false?'Đã khóa':'Hoạt động'])]);}});
  }});

  // Automatic promotion programs ------------------------------------------
  function voucherState(v){const today=M.today();if(v.active===false)return['disabled','Đã tắt','neutral'];if(v.startDate>today)return['upcoming','Sắp diễn ra','blue'];if(v.endDate<today)return['expired','Hết hạn','red'];if(v.limit>0&&v.used>=v.limit)return['used','Hết lượt','neutral'];return['active','Đang áp dụng','green'];}
  const vouchersFiltered=()=>arr(M.data,'vouchers').filter(v=>Search.match(v.name,ui.voucherQuery)&&(ui.voucherStatus==='all'||voucherState(v)[0]===ui.voucherStatus));
  function voucherRows(){
    const programs=vouchersFiltered();
    return programs.length?programs.map(v=>{const status=voucherState(v);return `<tr><td><strong>${esc(v.name)}</strong></td><td><strong>${v.type==='percent'?`${Number(v.value)||0}%`:cash(v.value)}</strong><small class="amp-row-sub">${v.type==='percent'&&v.maxDiscount>0?'Tối đa '+cash(v.maxDiscount):'Đơn từ '+cash(v.minOrder)}</small></td><td class="amp-min">${esc(dateOnly(v.startDate))}<small class="amp-row-sub">đến ${esc(dateOnly(v.endDate))}</small></td><td>${v.tier==='all'?'Tất cả khách hàng':'Từ hạng '+tierBadge(v.tier)}<small class="amp-row-sub">Đơn từ ${cash(v.minOrder)}</small></td><td>${Number(v.used)||0} / ${v.limit>0?v.limit:'∞'}</td><td>${M.badge(status[1],status[2])}</td><td><div class="am-actions"><button type="button" class="am-btn secondary small" data-voucher-edit="${esc(v.id)}">Sửa</button><button type="button" class="am-btn ghost small" data-voucher-toggle="${esc(v.id)}">${v.active===false?'Bật':'Tắt'}</button></div></td></tr>`;}).join(''):`<tr><td colspan="7">${M.empty('Chưa có chương trình phù hợp')}</td></tr>`;
  }
  function voucherForm(program=null){
    const v=program||{};
    M.dialog({title:v.id?'Sửa chương trình ưu đãi':'Thêm chương trình ưu đãi',wide:true,submitLabel:v.id?'Lưu chương trình':'Thêm chương trình',body:`<div class="am-form-grid">${field('Tên chương trình *','name',v.name,'required maxlength="150" placeholder="Ưu đãi cuối tháng"')}${selectField('Hình thức giảm','type',[['percent','Giảm theo phần trăm'],['fixed','Giảm số tiền cố định']],v.type||'percent')}${field('Giá trị giảm *','value',v.value??10,'required min="1" max="1000000000" step="1"','number')}${field('Giảm tối đa (đ, 0 = không giới hạn)','maxDiscount',v.maxDiscount??100000,'min="0" max="1000000000" step="1"','number')}${field('Đơn tối thiểu (đ)','minOrder',v.minOrder??0,'min="0" max="1000000000" step="1"','number')}${field('Ngày bắt đầu *','startDate',v.startDate||M.today(),'required','date')}${field('Ngày kết thúc *','endDate',v.endDate||M.today(),'required','date')}${field('Lượt tối đa (0 = không giới hạn)','limit',v.limit??0,'min="0" max="1000000" step="1"','number')}${selectField('Hạng tối thiểu','tier',[['all','Tất cả khách hàng'],...tiers.map(t=>[t,t])],v.tier||'all')}${activeField(v.active!==false)}</div>${v.used>0?`<p class="am-muted">Đã dùng: ${Number(v.used)} lượt</p>`:''}`,onOpen(form){
      const update=()=>{const percent=form.elements.type.value==='percent';form.elements.value.max=percent?'100':'1000000000';form.elements.maxDiscount.closest('label').hidden=!percent;const label=form.elements.value.closest('label');if(label.firstChild.nodeType===3)label.firstChild.textContent=percent?'Mức giảm (%) *':'Số tiền giảm (đ) *';};
      const dates=()=>{form.elements.endDate.min=form.elements.startDate.value;};
      form.elements.type.addEventListener('change',update);form.elements.startDate.addEventListener('change',dates);update();dates();
    },onSubmit:async form=>{
      const startDate=val(form,'startDate'),endDate=val(form,'endDate');if(endDate<startDate)throw new Error('Ngày kết thúc không được trước ngày bắt đầu.');
      const limit=numeric(form,'limit');if(limit>0&&limit<(Number(v.used)||0))throw new Error('Giới hạn lượt dùng không được thấp hơn số lượt đã sử dụng.');
      await E.saveVoucher({id:v.id,name:val(form,'name'),type:val(form,'type'),value:numeric(form,'value'),maxDiscount:val(form,'type')==='percent'?numeric(form,'maxDiscount'):0,minOrder:numeric(form,'minOrder'),startDate,endDate,limit,tier:val(form,'tier'),active:form.elements.active.checked});
      await refreshSaved(v.id?'Đã cập nhật chương trình ưu đãi.':'Đã thêm chương trình ưu đãi.');
    }});
  }
  M.register('vouchers',{title:'Ưu đãi',kicker:'Chương trình ưu đãi',render(){
    const programs=arr(M.data,'vouchers');
    return `<div class="am-stat-grid">${stat('Đang áp dụng',String(programs.filter(v=>voucherState(v)[0]==='active').length))}${stat('Sắp diễn ra',String(programs.filter(v=>voucherState(v)[0]==='upcoming').length))}${stat('Lượt đã sử dụng',String(programs.reduce((n,v)=>n+(Number(v.used)||0),0)))}${stat('Tổng chương trình',String(programs.length))}</div><div class="am-panel">${panelHead('Chương trình ưu đãi','',`<button type="button" class="am-btn secondary" data-vouchers-export>Xuất CSV</button><button type="button" class="am-btn" data-voucher-add>Thêm chương trình</button>`)}<div class="am-toolbar"><input type="search" class="am-search" data-voucher-query value="${esc(ui.voucherQuery)}" placeholder="Tìm tên chương trình…" aria-label="Tìm chương trình ưu đãi"><select data-voucher-status aria-label="Lọc trạng thái ưu đãi">${[['all','Tất cả trạng thái'],['active','Đang áp dụng'],['upcoming','Sắp diễn ra'],['expired','Hết hạn'],['used','Hết lượt'],['disabled','Đã tắt']].map(([v,t])=>`<option value="${v}"${selected(ui.voucherStatus,v)}>${t}</option>`).join('')}</select><span class="amp-count" data-voucher-count>${vouchersFiltered().length} chương trình</span></div><div class="am-table-wrap"><table class="am-table"><thead><tr><th>Chương trình</th><th>Mức giảm</th><th>Thời gian áp dụng</th><th>Điều kiện</th><th>Đã dùng</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody data-voucher-rows>${voucherRows()}</tbody></table></div></div>`;
  },bind(root){
    const update=()=>{root.querySelector('[data-voucher-rows]').innerHTML=voucherRows();root.querySelector('[data-voucher-count]').textContent=vouchersFiltered().length+' chương trình';};
    root.querySelector('[data-voucher-query]').addEventListener('input',e=>{ui.voucherQuery=e.target.value;update();});
    root.querySelector('[data-voucher-status]').addEventListener('change',e=>{ui.voucherStatus=e.target.value;update();});
    Search.attach(root.querySelector('[data-voucher-query]'), {items: () => vouchersFiltered().map(v => ({value: v.name, label: v.name, detail: [voucherState(v)[1], dateOnly(v.startDate) + ' – ' + dateOnly(v.endDate)].join(' · '), searchText: v.name}))});
    root.addEventListener('click',async e=>{
      const b=e.target.closest('button');if(!b)return;
      if(b.hasAttribute('data-voucher-add'))voucherForm();
      if(b.dataset.voucherEdit){const v=arr(M.data,'vouchers').find(x=>x.id===b.dataset.voucherEdit);if(v)voucherForm(v);}
      if(b.dataset.voucherToggle){const v=arr(M.data,'vouchers').find(x=>x.id===b.dataset.voucherToggle);if(!v)return;b.disabled=true;try{await E.saveVoucher({...v,active:v.active===false});await refreshSaved(v.active===false?'Đã bật chương trình ưu đãi.':'Đã tắt chương trình ưu đãi.');}catch(error){M.toast(error.message);b.disabled=false;}}
      if(b.hasAttribute('data-vouchers-export'))M.downloadCSV('Atino_uu_dai.csv',[['Tên chương trình','Hình thức','Giá trị','Giảm tối đa','Đơn tối thiểu','Bắt đầu','Kết thúc','Giới hạn','Đã dùng','Hạng tối thiểu','Trạng thái'],...vouchersFiltered().map(v=>[v.name,v.type==='percent'?'Phần trăm':'Số tiền',v.value,v.maxDiscount,v.minOrder,v.startDate,v.endDate,v.limit||'Không giới hạn',v.used,v.tier==='all'?'Tất cả khách hàng':v.tier,voucherState(v)[1]])]);
    });
  }});

  // Fixed customer policies and editable exchange conditions --------------
  M.register('settings',{title:'Chính sách',kicker:'Thiết lập quản lý',render(){
    const s=M.data.settings||{};
    const policyValue=(label,value)=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`;
    return `
    <div class="amp-policy-grid amp-policy-layout">
      <section class="am-panel amp-policy-card">
        <span class="amp-policy-tag">Thành viên</span>
        ${panelHead('Hạng khách hàng')}
        <dl class="amp-policy-values">
          ${policyValue('Hạng Đồng','Từ '+M.money(0))}
          ${policyValue('Hạng Bạc','Từ '+M.money(s.tierSilver))}
          ${policyValue('Hạng Vàng','Từ '+M.money(s.tierGold))}
          ${policyValue('Hạng Kim cương','Từ '+M.money(s.tierDiamond))}
        </dl>
      </section>
      <section class="am-panel amp-policy-card">
        <span class="amp-policy-tag">Sinh nhật</span>
        ${panelHead('Ưu đãi sinh nhật','Đúng ngày sinh · 1 lần/năm')}
        <div class="amp-birthday-value"><strong>${esc(s.birthdayPercent)}<span>%</span></strong>${M.badge('Tự động áp dụng','green')}</div>
        <dl class="amp-policy-values amp-birthday-limits">
          ${policyValue('Giảm tối đa',M.money(s.birthdayMax))}
          ${policyValue('Đơn tối thiểu',M.money(s.birthdayMin))}
        </dl>
      </section>
      <section class="am-panel amp-policy-card amp-full">
        <span class="amp-policy-tag">Đổi hàng</span>
        ${panelHead('Chính sách đổi hàng')}
        <div class="am-grid-3 amp-exchange-summary">
          <div><div class="amp-policy-numbers"><strong>30</strong><span>ngày kể từ khi mua</span></div></div>
          <div><h3>Đổi ngang giá hoặc cao hơn</h3><p class="am-muted">Thu chênh lệch · Không hoàn tiền</p></div>
          <div><h3>Hàng nhận lại</h3><p class="am-muted">Đạt yêu cầu: nhập lại cửa hàng<br>Hàng lỗi: chờ xử lý</p></div>
        </div>
        <form data-policy-form="returns" class="amp-settings-form">
          <label class="am-field"><span>Điều kiện kiểm tra và ghi chú</span><textarea rows="4" name="returnConditions" required maxlength="2000">${esc(s.returnConditions||'Có hóa đơn mua hàng; sản phẩm còn nguyên tem, chưa qua sử dụng. Nhân viên kiểm tra tình trạng trước khi quản lý xác nhận đổi hàng.')}</textarea></label>
          <div class="am-actions amp-policy-actions"><button class="am-btn" type="submit">Lưu điều kiện đổi hàng</button><button type="button" class="am-btn secondary" data-open-returns>Đến quản lý đổi hàng</button></div>
          <p class="am-error" role="alert" data-local-error hidden></p>
        </form>
      </section>
    </div>`;
  },bind(root){root.querySelector('[data-policy-form="returns"]').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const button=form.querySelector('button[type=submit]');if(button.disabled)return;button.disabled=true;formError(form,'');try{await E.saveSettings({returnConditions:val(form,'returnConditions')});await refreshSaved('Đã lưu điều kiện đổi hàng.');}catch(error){formError(form,error.message);button.disabled=false;}});root.querySelector('[data-open-returns]').addEventListener('click',()=>M.go('returns'));}});
})();
